// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract JAXX is ERC721URIStorage, Ownable {
    uint256 private _tokenIdCounter;

    constructor(address initialOwner) ERC721("JAXX Service Animal NFT", "JAXX") Ownable(initialOwner) {}

    function mintServiceBadge(address to, string memory uri) public onlyOwner {
        uint256 tokenId = _tokenIdCounter;
        _tokenIdCounter += 1;
        _safeMint(to, tokenId);
        _setTokenURI(tokenId, uri);
    }

    function currentTokenId() public view returns (uint256) {
        return _tokenIdCounter;
    }
}

contracts/VALOR_Sim.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract VALOR_Sim {
    address public owner;

    enum Role { Unknown, Judge, Lawyer, Defendant }

    struct LegalProfile {
        string name;
        Role role;
        uint256 riskScore;
        uint256 lastUpdated;
    }

    mapping(address => LegalProfile) public profiles;
    mapping(address => bool) public authorizedAnalysts;

    event ProfileCreated(address indexed user, string name, Role role);
    event RiskUpdated(address indexed user, uint256 riskScore);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyAnalyst() {
        require(authorizedAnalysts[msg.sender], "Not authorized");
        _;
    }

    constructor() {
        owner = msg.sender;
        authorizedAnalysts[msg.sender] = true;
    }

    function authorizeAnalyst(address analyst, bool status) external onlyOwner {
        authorizedAnalysts[analyst] = status;
    }

    function registerProfile(address user, string calldata name, Role role) external onlyAnalyst {
        profiles[user] = LegalProfile(name, role, 0, block.timestamp);
        emit ProfileCreated(user, name, role);
    }

    function updateRiskScore(address user, uint256 newScore) external onlyAnalyst {
        require(bytes(profiles[user].name).length > 0, "Profile not found");
        profiles[user].riskScore = newScore;
        profiles[user].lastUpdated = block.timestamp;
        emit RiskUpdated(user, newScore);
    }

    function getProfile(address user) external view returns (string memory, Role, uint256, uint256) {
        LegalProfile memory p = profiles[user];
        return (p.name, p.role, p.riskScore, p.lastUpdated);
    }
}

contracts/VALOR_Witness.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract VALOR_Witness {
    address public controller;

    struct ModelSnapshot {
        string modelName;
        string ipfsCID;
        string ethAnchor;
        uint256 timestamp;
        address submittedBy;
    }

    mapping(bytes32 => ModelSnapshot) public snapshots;
    mapping(address => bool) public trustedAgents;

    event SnapshotAnchored(
        bytes32 indexed id,
        string modelName,
        string ipfsCID,
        string ethAnchor,
        uint256 timestamp,
        address indexed submittedBy
    );

    modifier onlyController() {
        require(msg.sender == controller, "Not authorized");
        _;
    }

    modifier onlyTrustedAgent() {
        require(trustedAgents[msg.sender], "Not a trusted agent");
        _;
    }

    constructor() {
        controller = msg.sender;
        trustedAgents[msg.sender] = true;
    }

    function authorizeAgent(address agent, bool status) external onlyController {
        trustedAgents[agent] = status;
    }

    function anchorSnapshot(
        bytes32 id,
        string calldata modelName,
        string calldata ipfsCID,
        string calldata ethAnchor
    ) external onlyTrustedAgent {
        require(bytes(snapshots[id].modelName).length == 0, "Snapshot already exists");

        snapshots[id] = ModelSnapshot({
            modelName: modelName,
            ipfsCID: ipfsCID,
            ethAnchor: ethAnchor,
            timestamp: block.timestamp,
            submittedBy: msg.sender
        });

        emit SnapshotAnchored(id, modelName, ipfsCID, ethAnchor, block.timestamp, msg.sender);
    }

    function getSnapshot(bytes32 id) public view returns (string memory, string memory, string memory, uint256, address) {
        ModelSnapshot memory snap = snapshots[id];
        return (snap.modelName, snap.ipfsCID, snap.ethAnchor, snap.timestamp, snap.submittedBy);
    }
}

